  // src/core/propsTranslator.ts
  var twProps = props_default;
  var trans4twProps = (text) => {
    if (!text) return text;
    if (twProps[text]) {
      return twProps[text];
    }
    const list = text.split(" ");
    let trans = "";
    list.forEach((item) => {
      if (twProps[item]) {
        trans += twProps[item];
      }
    });
    if (trans) return trans;
    const find = Object.keys(twProps).find((a) => text.includes(a));
    if (find) {
      return text.replace(find, twProps[find]);
    }
    return text;
  };

